return [{
  json: {
    keywords: 'software engineer',
    location: 'London, United Kingdom',
    datePosted: 'pastWeek',
    limit: 25,
    budgetUsd: 0.05,
    scrapeCompany: false,
    sheetId: 'smoke_sheet_id',
    sheetName: 'Jobs'
  }
}];

const config = $input.first()?.json ?? {};

function requiredText(value, name) {
  if (typeof value !== 'string' || !value.trim()) {
    throw new Error(`${name} must be a non-empty string`);
  }
  return value.trim();
}

function positiveInteger(value, name, maximum) {
  if (!Number.isInteger(value) || value < 1 || value > maximum) {
    throw new Error(`${name} must be an integer from 1 to ${maximum}`);
  }
  return value;
}

const datePostedValues = new Set(['anyTime', 'past24Hours', 'pastWeek', 'pastMonth']);
const datePosted = requiredText(config.datePosted, 'datePosted');
if (!datePostedValues.has(datePosted)) {
  throw new Error(`datePosted must be one of ${[...datePostedValues].join(', ')}`);
}

const budgetUsd = Number(config.budgetUsd);
if (!Number.isFinite(budgetUsd) || budgetUsd <= 0) {
  throw new Error('budgetUsd must be a positive number');
}

const limit = positiveInteger(config.limit, 'limit', 1000);
const sheetId = requiredText(config.sheetId, 'sheetId');
if (!/^[A-Za-z0-9_-]{2,}$/.test(sheetId)) {
  throw new Error('sheetId must be the Google Sheets document ID');
}

return [{
  json: {
    keywords: requiredText(config.keywords, 'keywords'),
    location: requiredText(config.location, 'location'),
    datePosted,
    limit,
    count: limit,
    limitPerSource: limit,
    scrapeCompany: config.scrapeCompany === true,
    budgetUsd,
    sheetId,
    sheetName: requiredText(config.sheetName, 'sheetName'),
    actorTimeoutSeconds: 300,
    waitForFinishSeconds: 60,
    pollDelaySeconds: 5,
    maxPollAttempts: 6,
    runDeadlineEpochMs: Date.now() + 480_000,
  },
}];

return [{
  json: {
    body: {
      data: {
        id: 'smoke-run',
        status: 'RUNNING',
        defaultDatasetId: 'smoke-dataset'
      }
    }
  }
}];

const response = $input.first()?.json ?? {};
const settings = $('Input Validation').first()?.json ?? {};

let body = response.body !== undefined ? response.body : response;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    throw new Error('Apify start response was not valid JSON');
  }
}

const run = body?.data ?? body;
if (!run || typeof run !== 'object') {
  throw new Error('Apify start response did not contain a run');
}

const runId = String(run.id ?? '').trim();
if (!runId) {
  throw new Error('Apify start response did not contain a run ID');
}

const status = String(run.status ?? '').trim().toUpperCase();
const datasetId = String(run.defaultDatasetId ?? '').trim();
const state = {
  ...settings,
  runId,
  datasetId,
  status,
  pollCount: 0,
};

if (status === 'SUCCEEDED') {
  if (!datasetId) {
    throw new Error(`Actor run ${runId} succeeded without a defaultDatasetId`);
  }
  return [{ json: { ...state, nextAction: 'fetch' } }];
}

if (status === 'READY' || status === 'RUNNING') {
  if (Date.now() >= settings.runDeadlineEpochMs) {
    throw new Error(`Actor run ${runId} is still ${status} after the local deadline. Recovery run ID: ${runId}`);
  }
  return [{ json: { ...state, nextAction: 'poll' } }];
}

throw new Error(`Actor run ${runId} ended with status ${status || 'UNKNOWN'}. Recovery run ID: ${runId}`);

const state = $('Wait for Actor').first()?.json ?? {};
const nextPoll = Number(state.pollCount ?? 0) + 1;
return [{
  json: {
    body: {
      data: {
        id: state.runId,
        status: nextPoll >= 2 ? 'SUCCEEDED' : 'RUNNING',
        defaultDatasetId: state.datasetId
      }
    }
  }
}];

const previous = $('Wait for Actor').first()?.json ?? {};
const response = $input.first()?.json ?? {};
const settings = $('Input Validation').first()?.json ?? {};

let body = response.body !== undefined ? response.body : response;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    throw new Error(`Apify poll response for run ${previous.runId ?? 'UNKNOWN'} was not valid JSON`);
  }
}

const run = body?.data ?? body;
if (!run || typeof run !== 'object') {
  throw new Error(`Apify poll response did not contain run ${previous.runId ?? 'UNKNOWN'}`);
}

const runId = String(run.id ?? previous.runId ?? '').trim();
if (!runId || runId !== previous.runId) {
  throw new Error(`Apify poll response changed or omitted run ID ${previous.runId ?? 'UNKNOWN'}`);
}

const status = String(run.status ?? '').trim().toUpperCase();
const datasetId = String(run.defaultDatasetId ?? previous.datasetId ?? '').trim();
const pollCount = Number(previous.pollCount ?? 0) + 1;
const state = {
  ...previous,
  status,
  datasetId,
  pollCount,
};

if (status === 'SUCCEEDED') {
  if (!datasetId) {
    throw new Error(`Actor run ${runId} succeeded without a defaultDatasetId`);
  }
  return [{ json: { ...state, nextAction: 'fetch' } }];
}

if (status === 'READY' || status === 'RUNNING') {
  if (Date.now() >= settings.runDeadlineEpochMs) {
    throw new Error(`Actor run ${runId} is still ${status} after the local deadline. Recovery run ID: ${runId}`);
  }
  if (pollCount >= settings.maxPollAttempts) {
    throw new Error(`Actor run ${runId} did not finish after ${pollCount} polls. Recovery run ID: ${runId}`);
  }
  return [{ json: { ...state, nextAction: 'poll' } }];
}

throw new Error(`Actor run ${runId} ended with status ${status || 'UNKNOWN'}. Recovery run ID: ${runId}`);

return [{
  json: {
    body: {
      status: 'completed',
      delivered: 2,
      uniqueJobs: 2,
      searchPages: 1,
      failedSearches: 0,
      failedJobDetails: 0,
      failedCompanies: 0,
      stoppedByBudget: false,
      cacheHits: 0
    }
  }
}];

const response = $input.first()?.json ?? {};
const state = $('Is Run Succeeded?').first()?.json ?? {};

let body = response.body !== undefined ? response.body : response;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    throw new Error(`Actor run ${state.runId ?? 'UNKNOWN'} returned an invalid OUTPUT summary`);
  }
}
const summary = body?.data ?? body;
if (!summary || typeof summary !== 'object' || Array.isArray(summary)) {
  throw new Error(`Actor run ${state.runId ?? 'UNKNOWN'} returned an invalid OUTPUT summary`);
}

const numericFields = [
  'delivered',
  'uniqueJobs',
  'searchPages',
  'failedSearches',
  'failedJobDetails',
  'failedCompanies',
  'cacheHits',
];
const clean = { status: String(summary.status ?? '') };
for (const field of numericFields) {
  const value = summary[field];
  if (!Number.isInteger(value) || value < 0) {
    throw new Error(`Actor run ${state.runId ?? 'UNKNOWN'} OUTPUT summary has an invalid ${field}`);
  }
  clean[field] = value;
}
if (typeof summary.stoppedByBudget !== 'boolean') {
  throw new Error(`Actor run ${state.runId ?? 'UNKNOWN'} OUTPUT summary has an invalid stoppedByBudget`);
}
clean.stoppedByBudget = summary.stoppedByBudget;

if (clean.failedSearches > 0) {
  throw new Error(
    `Actor run ${state.runId ?? 'UNKNOWN'} completed with ${clean.failedSearches} failed search(es); no dataset was accepted. Recovery run ID: ${state.runId ?? 'UNKNOWN'}`,
  );
}

clean.coverage = (
  clean.failedJobDetails > 0
  || clean.failedCompanies > 0
  || clean.stoppedByBudget
) ? 'partial' : 'complete';

return [{
  json: {
    ...state,
    actorSummary: clean,
    coverage: clean.coverage,
  },
}];

return [{
  json: {
    body: [
      {
        id: '1001',
        title: 'Smoke Test Engineer',
        companyName: 'Example Co',
        location: 'London, United Kingdom',
        postedAt: '2026-10-24',
        link: 'https://www.linkedin.com/jobs/view/ing%C3%A9nieur%20logiciel-1001?keywords=software%20engineer',
        salary: '',
        employmentType: 'Full-time',
        seniorityLevel: 'Mid-Senior level'
      },
      {
        id: '1002',
        title: 'Second Smoke Test Engineer',
        companyName: 'Example Co',
        location: 'London, United Kingdom',
        postedAt: '2026-10-24',
        link: 'https://uk.linkedin.com/jobs/view/développeur-logiciel-1002',
        salary: '',
        employmentType: 'Full-time',
        seniorityLevel: 'Mid-Senior level'
      }
    ]
  }
}];

const response = $input.first()?.json ?? {};
const run = $('Assess Run Output').first()?.json ?? {};

let body = response.body !== undefined ? response.body : response;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    throw new Error(`Dataset ${run.datasetId ?? 'UNKNOWN'} did not return valid JSON`);
  }
}
if (!Array.isArray(body) && Array.isArray(body?.data)) {
  body = body.data;
}
if (!Array.isArray(body)) {
  throw new Error(`Dataset ${run.datasetId ?? 'UNKNOWN'} response must be an array`);
}

function text(value) {
  return value == null ? '' : String(value).trim();
}

function linkedInJobPathId(link, label) {
  if (
    typeof link !== 'string'
    || link !== link.trim()
    || /[\s\\\u0000-\u001f\u007f-\u009f]/u.test(link)
    || /%(?![0-9a-f]{2})/iu.test(link)
  ) {
    throw new Error(`${label} has an invalid link`);
  }

  for (const match of link.matchAll(/%([0-9a-f]{2})/giu)) {
    const byte = Number.parseInt(match[1], 16);
    if (byte < 0x20 || byte === 0x5c || byte === 0x7f) {
      throw new Error(`${label} has an unsafe percent-encoded character in its link`);
    }
  }

  if (!/^https:\/\//i.test(link)) {
    throw new Error(`${label} link must be a public LinkedIn HTTPS URL in /jobs/view/<job-id> form`);
  }
  const rest = link.slice('https://'.length);
  const suffixStart = rest.search(/[?#]/);
  const authorityAndPath = suffixStart === -1 ? rest : rest.slice(0, suffixStart);
  const slash = authorityAndPath.indexOf('/');
  if (slash <= 0) {
    throw new Error(`${label} link must be a public LinkedIn HTTPS URL in /jobs/view/<job-id> form`);
  }

  const authority = authorityAndPath.slice(0, slash);
  if (
    authority.includes('@')
    || authority.includes(':')
    || !/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)*linkedin\.com$/i.test(authority)
  ) {
    throw new Error(`${label} link must use a public LinkedIn HTTPS authority`);
  }

  const path = authorityAndPath.slice(slash);
  const prefix = '/jobs/view/';
  if (!path.startsWith(prefix)) {
    throw new Error(`${label} link must be a LinkedIn job view URL`);
  }
  let slug = path.slice(prefix.length);
  if (slug.endsWith('/')) slug = slug.slice(0, -1);
  if (!slug || slug.includes('/')) {
    throw new Error(`${label} link must contain one non-empty job slug`);
  }

  const pathIdMatch = /(?:^|[-_])([0-9]+)$/.exec(slug);
  if (!pathIdMatch) {
    throw new Error(`${label} link does not end with a numeric job ID`);
  }
  return pathIdMatch[1];
}

function requirePublicJob(item, index) {
  if (!item || typeof item !== 'object' || Array.isArray(item)) {
    throw new Error(`Dataset item ${index} is not an object`);
  }
  const id = text(item.id);
  const title = text(item.title);
  const link = item.link;
  if (!/^[0-9]+$/.test(id)) {
    throw new Error(`Dataset item ${index} has an invalid id`);
  }
  if (!title) {
    throw new Error(`Dataset item ${index} is missing title`);
  }
  const pathId = linkedInJobPathId(link, `Dataset item ${index}`);
  if (pathId !== id) {
    throw new Error(`Dataset item ${index} link job ID does not match its id`);
  }
  return { id, title, link };
}

const firstSeenAt = new Date().toISOString();
const jobs = body.map((item, index) => {
  const publicJob = requirePublicJob(item, index);
  return {
    id: publicJob.id,
    title: publicJob.title,
    company: text(item.companyName),
    location: text(item.location),
    postedAt: text(item.postedAt),
    url: publicJob.link,
    salary: text(item.salary),
    employmentType: text(item.employmentType),
    seniority: text(item.seniorityLevel),
    firstSeenAt,
  };
});

return [{
  json: {
    jobs,
    runId: run.runId,
    datasetId: run.datasetId,
    status: run.status,
    count: run.count,
    sheetId: run.sheetId,
    sheetName: run.sheetName,
    actorSummary: run.actorSummary,
    coverage: run.coverage,
    fetchedCount: jobs.length,
  },
}];

const source = $('Normalize Jobs').first()?.json ?? {};
const tableItems = $input.all();

function text(value) {
  return value == null ? '' : String(value).trim();
}

function linkedInJobPathId(link, label) {
  if (
    typeof link !== 'string'
    || link !== link.trim()
    || /[\s\\\u0000-\u001f\u007f-\u009f]/u.test(link)
    || /%(?![0-9a-f]{2})/iu.test(link)
  ) {
    throw new Error(`${label} has an invalid link`);
  }

  for (const match of link.matchAll(/%([0-9a-f]{2})/giu)) {
    const byte = Number.parseInt(match[1], 16);
    if (byte < 0x20 || byte === 0x5c || byte === 0x7f) {
      throw new Error(`${label} has an unsafe percent-encoded character in its link`);
    }
  }

  if (!/^https:\/\//i.test(link)) {
    throw new Error(`${label} link must be a public LinkedIn HTTPS URL in /jobs/view/<job-id> form`);
  }
  const rest = link.slice('https://'.length);
  const suffixStart = rest.search(/[?#]/);
  const authorityAndPath = suffixStart === -1 ? rest : rest.slice(0, suffixStart);
  const slash = authorityAndPath.indexOf('/');
  if (slash <= 0) {
    throw new Error(`${label} link must be a public LinkedIn HTTPS URL in /jobs/view/<job-id> form`);
  }

  const authority = authorityAndPath.slice(0, slash);
  if (
    authority.includes('@')
    || authority.includes(':')
    || !/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)*linkedin\.com$/i.test(authority)
  ) {
    throw new Error(`${label} link must use a public LinkedIn HTTPS authority`);
  }

  const path = authorityAndPath.slice(slash);
  const prefix = '/jobs/view/';
  if (!path.startsWith(prefix)) {
    throw new Error(`${label} link must be a LinkedIn job view URL`);
  }
  let slug = path.slice(prefix.length);
  if (slug.endsWith('/')) slug = slug.slice(0, -1);
  if (!slug || slug.includes('/')) {
    throw new Error(`${label} link must contain one non-empty job slug`);
  }

  const pathIdMatch = /(?:^|[-_])([0-9]+)$/.exec(slug);
  if (!pathIdMatch) {
    throw new Error(`${label} link does not end with a numeric job ID`);
  }
  return pathIdMatch[1];
}

function publicId(value, label) {
  const id = text(value);
  if (!/^[0-9]+$/.test(id)) {
    throw new Error(`${label} has an invalid id`);
  }
  return id;
}

function validateJob(job, index) {
  if (!job || typeof job !== 'object' || Array.isArray(job)) {
    throw new Error(`Normalized job ${index} is not an object`);
  }
  const id = publicId(job.id, `Normalized job ${index}`);
  if (typeof job.title !== 'string' || !job.title.trim()) {
    throw new Error(`Normalized job ${index} is missing title`);
  }
  if (typeof job.url !== 'string') {
    throw new Error(`Normalized job ${index} is missing link`);
  }
  const pathId = linkedInJobPathId(job.url, `Normalized job ${index}`);
  if (pathId !== id) {
    throw new Error(`Normalized job ${index} link job ID does not match its id`);
  }
  return id;
}

if (!Array.isArray(source.jobs)) {
  throw new Error('Normalize Jobs did not return a jobs array');
}

const existingIds = new Set();
tableItems.forEach((item, rowIndex) => {
  const row = item?.json ?? {};
  const values = Object.entries(row)
    .filter(([key]) => key !== 'row_number')
    .map(([, value]) => value);
  const rowIsEmpty = values.every((value) => value == null || text(value) === '');
  if (rowIsEmpty) return;
  if (row.id == null || text(row.id) === '') {
    const sheetRow = text(row.row_number) || String(rowIndex + 1);
    throw new Error(`Existing sheet row ${sheetRow} has data but no id`);
  }
  existingIds.add(publicId(row.id, 'Existing sheet row'));
});

const fetchedIds = new Set();
const newJobs = [];
let skippedExisting = 0;
let skippedBatchDuplicates = 0;

source.jobs.forEach((job, index) => {
  const id = validateJob(job, index);
  if (existingIds.has(id)) {
    skippedExisting += 1;
  } else if (fetchedIds.has(id)) {
    skippedBatchDuplicates += 1;
  } else {
    fetchedIds.add(id);
    newJobs.push(job);
  }
});

const summary = {
  runId: source.runId,
  datasetId: source.datasetId,
  actorSummary: source.actorSummary,
  coverage: source.coverage,
  fetchedCount: source.jobs.length,
  newCount: newJobs.length,
  skippedExisting,
  skippedBatchDuplicates,
  hasNewJobs: newJobs.length > 0,
};

return [{ json: { newJobs, summary, hasNewJobs: summary.hasNewJobs } }];

const pollState = $('Assess Polled Run').first()?.json ?? {};
const outputState = $('Assess Run Output').first()?.json ?? {};
const normalized = $('Normalize Jobs').first()?.json ?? {};
const filtered = $('Filter New IDs').first()?.json ?? {};
const flatItems = $input.all();

if (pollState.pollCount !== 2 || pollState.status !== 'SUCCEEDED') {
  throw new Error('Expected the latest poll state to be SUCCEEDED after two polls');
}
if (outputState.pollCount !== 2 || outputState.runId !== 'smoke-run') {
  throw new Error('Assess Run Output did not recover the latest poll state');
}
if (normalized.fetchedCount !== 2 || normalized.jobs.length !== 2) {
  throw new Error('Normalize Jobs did not produce two jobs');
}
if (filtered.summary.newCount !== 2 || filtered.summary.skippedExisting !== 0) {
  throw new Error('Filter New IDs did not treat the row_number-only placeholder as empty');
}
if (flatItems.length !== 2) {
  throw new Error('Split Out New Jobs did not emit two flat items');
}

for (const [index, item] of flatItems.entries()) {
  const flat = item.json ?? {};
  if (!flat.id || flat.jobs || flat.newJobs) {
    throw new Error('Split Out New Jobs item ' + index + ' is not a flat job');
  }
  const urlPath = flat.url.replace(/[?#].*$/, '');
  const pathId = /(?:^|[-_])([0-9]+)$/.exec(urlPath)?.[1];
  if (pathId !== flat.id) {
    throw new Error('Split Out New Jobs item ' + index + ' has a URL job ID mismatch');
  }
}

return [{
  json: {
    status: 'passed',
    runId: outputState.runId,
    pollCount: pollState.pollCount,
    splitItemCount: flatItems.length,
    splitItemIds: flatItems.map((item) => item.json?.id),
    normalizedCount: normalized.fetchedCount,
    newCount: filtered.summary.newCount,
    coverage: outputState.coverage,
    urlGlobalType: typeof URL
  }
}];
